    /* ---------- method.html ---------- */
    "method.crumb": "cách chúng tôi làm việc",
    "method.h1": "Cách chúng tôi làm việc",
    "method.thesis": "Cách chúng tôi đã làm việc trực tiếp từ năm 2011 — một brief trung thực, một mức giá minh bạch, một đội được lập cho mục tiêu — được viết ra, số hóa và mở để bạn dùng, phản biện hoặc fork. Sản xuất mỗi năm một rẻ hơn; khác biệt nằm ở cách ghép đội.",
    "method.eb1": "điều chúng tôi liên tục gặp phải",
    "method.p1": "Bán đội theo ngày, theo bảng giá, lấy ai đang trên băng ghế là một mô hình có logic riêng: nó giữ băng ghế có việc và giữ pipeline dự đoán được, và nhiều việc tốt đã ra đời từ đó. Phần chúng tôi thấy khó là động lực nó tạo ra — phải tối ưu tỷ lệ sử dụng, nên những người làm việc trở nên có thể thay thế theo thiết kế, và quan hệ với khách hàng thuộc về công ty chứ không thuộc về những con người cùng xây. Đó là cách chúng tôi đọc nó, từ bên ngoài và từ hơn một lần làm nhà cung cấp nhỏ bên trong.",
    "method.p2": "Một đội liên chức năng được lập <em>cho</em> mục tiêu — những người tự thân và về chuyên môn nghiêng đúng vào vấn đề này, thay vì được điều chỉnh cho vừa — với chúng tôi đã làm việc tốt hơn. Chúng tôi không thể đưa ra một thử nghiệm đối chứng; chúng tôi có mười lăm năm dự án trong một phân khúc — công việc có giới hạn, hình dạng sản phẩm — nơi sự phù hợp dường như quan trọng hơn quy mô.",
    "method.eb2": "phương pháp — ba bước",
    "method.s1.n": "bước 1",
    "method.s1.h": "Brief Bar",
    "method.s1.p": "Công việc là gì. Một sản phẩm tuyệt vời là 20% brief và 80% đội ngũ — nhưng brief là 20% quyết định liệu một đội ngũ giỏi có thể bắt đầu tốt hay không. Được chấm theo quy tắc công khai, có cổng trước khi công bố.",
    "method.s1.go": "→ chấm một brief",
    "method.s2.n": "bước 2",
    "method.s2.h": "Price Split",
    "method.s2.p": "Nó đáng giá bao nhiêu, và ai nhận phần nào. Phần chia dựa trên mức độ một người đảm nhận vai trò — không bao giờ dựa trên phán xét về con người họ. Được tuyên bố sao cho ai cũng tính lại và kiểm tra được.",
    "method.s2.go": "→ tính một phần chia",
    "method.s3.n": "bước 3",
    "method.s3.h": "Team Rate",
    "method.s3.p": "Ai làm, ở đâu trên thế giới, với một mức giá gộp duy nhất mà khách hàng thực sự suy luận được. Biên lợi nhuận thay đổi trong đội theo cấp độ; dự án đạt một welance margin được tuyên bố; không ai bị ép xuống dưới mức giá của mình.",
    "method.s3.go": "→ tìm đội ngũ",
    "method.p3": "Mỗi bước cần bước trước nó. Giá cần phạm vi của brief để biết một vai trò là gì; đội ngũ cần phép tính của giá để cho ba con người một mức giá trung thực. Thông tin đổ xuống theo tầng — vì thế chúng là các bước chứ không phải tính năng, và vì thế brief vẫn là khái niệm chính: không gì ở hạ nguồn sống sót qua một brief thiếu trung thực.",
    "method.fxintro": "Mọi thứ phương pháp tính toán, sinh ra từ chính tệp mà các máy tính chạy trên đó (<a href=\"https://github.com/welance/perfect-brief/blob/main/site/pricing.js\">pricing.js</a>) — trang này không thể lệch khỏi mã nguồn.",
    "method.fxhead": "cả {n} công thức, đầy đủ",
    "method.fxclose": "<b>{n}</b> công thức này giúp đưa ra quyết định. Mọi thứ còn lại là vốn con người — và nó không tính toán được.",
    "method.eb3": "điều các công thức không thấy",
    "method.p4": "<b>Công việc bắt đầu thật sự.</b> Các công thức tạo ra đội ngũ <em>khởi đầu</em> — không phải chạy thử, không phải thí điểm: công việc thật khởi động. Điều không công thức nào thấy được chỉ học được qua cộng tác: sự tương thích văn hóa giữa các thành viên và với khách hàng, sự tử tế, tính nhân văn, sự sẵn sàng, cách một người chịu áp lực — cả khối kỹ năng mềm chỉ lộ ra khi áp lực là thật.",
    "method.p5": "Vì thế khởi đầu mang theo một điều khoản dự phòng công khai: các buổi kiểm tra theo lịch sau một-ba ngày, tuần hoặc tháng — tùy quy mô và độ phức tạp của dự án — nơi bất kỳ bên nào cũng có thể nói rằng nó không ổn, và các lựa chọn ban đầu có thể được thay thế, gỡ bỏ hoặc điều chỉnh. Hai chiều, luôn luôn: người độc lập cũng có thể thấy không thoải mái, và mọi vấn đề con người nên nổi lên ở lần kiểm tra đầu thay vì âm ỉ. Việc nổi lên sớm ấy là thứ ngăn bất mãn, không khí xấu và những dự án tồi.",
    "method.p6": "Trong công việc trí óc, ý tưởng, trực giác và độ mềm dẻo tư duy cần không gian để chuyển thành thành công. Khi có gì đó lệch, sự điều chỉnh được thực hiện trên tài sản quan trọng nhất: con người.",
    "method.eb4": "vì sao mở",
    "method.p7": "Đây là điều chúng tôi đã làm với tư cách một agency, trực tiếp, dự án này qua dự án khác. Viết ra và mở nó biến một cách làm thành thứ ai cũng kiểm tra được: quy tắc mở cho brief, một tệp đọc được cho giá, một phương trình cho đội — MIT như phần còn lại, để một tập thể không đồng ý với các con số của chúng tôi có thể fork và chạy bản của họ. Mô hình thì mở; thành viên thì được tuyển chọn. Cái chúng tôi thu tiền là việc tuyển chọn, và nói thẳng điều đó cũng thuộc về phần công khai.",
    "method.p8": "Một tập thể định giá như vậy bền bỉ theo cách một mạng lưới bền bỉ: không băng ghế phải nuôi, không hình dạng cố định để gãy, một quỹ dự trữ công khai thay vì giấu kín. Lời khẳng định vẫn nhỏ và đúng: một brief bạn chấm được, một phần chia bạn tính được, một đội ngũ bạn suy luận được — và một buổi kiểm tra trung thực, sớm, nơi con người quyết định điều công thức không thể.",
    "method.l6": "Dấu vết còn cũ hơn trang này: cuộc khảo sát dân du mục số toàn cầu đầu tiên, Coconat, các dự án phát triển nông thôn, những quan hệ đối tác đã hơn một thập kỷ — từ con số không.",
    "method.l5": "Viết một cách làm ra giấy khiến nó kiểm chứng được: quy tắc mở, một tệp đọc được, một phương trình — MIT, để một tập thể không đồng ý với các con số của chúng tôi có thể fork và chạy bản của họ. Cái chúng tôi thu tiền là việc tuyển chọn, và điều đó cũng nên nói công khai.",
    "method.c5": "Mô hình thì mở. Thành viên thì được tuyển chọn.",
    "method.l4": "Các công thức tạo ra đội ngũ khởi đầu — không phải chạy thử, không phải thí điểm: công việc thật khởi động. Điều không công thức nào thấy chỉ học được qua cộng tác: sự tương thích, sự tử tế, cách một người chịu áp lực.",
