    /* ---------- data.html — your brief, your key ---------- */
    "data.crumb": "brief của bạn, khoá của bạn",
    "data.h1": "Brief của bạn, khoá của bạn",
    "data.thesis": "Một dự án đề nghị bạn tin vào một thước đo mở thì cũng nợ bạn những chi tiết buồn tẻ: cái gì rời khỏi máy bạn, chúng tôi giữ gì, giữ bao lâu, và cái gì không bao giờ giữ.",
    "data.eb1": "cái gì đi đâu",
    "data.th1": "cái gì",
    "data.th2": "đi đâu",
    "data.th3": "chúng tôi giữ gì",
    "data.r1.k": "Nội dung brief",
    "data.r1.a": "Tới dịch vụ của chúng tôi, rồi tới nhà cung cấp mô hình chấm nó — mặc định là Anthropic, hoặc OpenRouter khi bạn mang khoá riêng.",
    "data.r1.b": "không bao giờ lưu",
    "data.r2.k": "Các phán quyết",
    "data.r2.a": "Trả về cho bạn. Mỗi phán quyết kèm một trích dẫn ngắn sao nguyên văn từ brief của bạn làm bằng chứng.",
    "data.r2.b": "lưu tạm 24 giờ",
    "data.r2.c": "— lập chỉ mục theo một hash của bản brief, nên cùng một brief không bị chấm lại và tính phí lại. Điều này đúng cả khi bạn mang khoá của mình: bộ nhớ đệm là dùng chung, nên một brief giống hệt có thể được trả lời từ đó thay vì bị tính phí lần nữa. Gửi <code>no_cache: true</code> thì không đọc và cũng không ghi gì cả.",
    "data.r3.k": "Khoá mô hình của bạn",
    "data.r3.a": "Chuyển tiếp đúng một lần, qua TLS, tới nhà cung cấp — như header Authorization của riêng lệnh gọi đó.",
    "data.r3.b": "không bao giờ lưu, không ghi log, không nằm trong khoá cache",
    "data.r4.k": "Bạn là ai",
    "data.r4.a": "Không ở đâu cả. Không tài khoản, không cookie, không analytics trên các trang này.",
    "data.r4.b": "không có gì để giữ",
    "data.cache": "Bộ nhớ đệm tồn tại vì một lý do: bộ chấm là tất định ở nhiệt độ 0, nên chấm cùng một brief hai lần lẽ ra chỉ tốn một lần và trả lời y hệt. Nó giữ các phán quyết — trạng thái, độ tin cậy, một trích dẫn ngắn — không bao giờ giữ brief, và hết hạn sau một ngày.",
    "data.eb2": "mang khoá của riêng bạn",
    "data.c1": "Với khoá của bạn, chúng tôi không chạy mô hình nào cho bạn.",
    "data.byok": "Gửi khoá OpenRouter trong header <code>x-llm-key</code> và việc chấm chạy trên tài khoản của bạn, với bất kỳ mô hình nào bạn chọn. Chúng tôi chuyển tiếp lệnh gọi và trao lại kết quả — không mô hình nào của chúng tôi được gọi, và không giữ lại gì về khoá.",
    "data.byokLabel": "bộ chấm của riêng bạn",
    "data.mcpkey": "<a href=\"integrate.html#mcp\">Máy chủ MCP</a> đọc cùng khoá đó từ <code>PB_LLM_KEY</code>, nên một trợ lý trên máy bạn có thể chấm brief hoàn toàn bằng tài khoản của bạn.",
    "data.eb3": "nếu vẫn chưa đủ",
    "data.custom": "Có những brief không được rời khỏi một vành đai, và có tổ chức cần thoả thuận xử lý dữ liệu, một mô hình cụ thể, hoặc chạy toàn bộ ở nơi khác. Đó là một cuộc trò chuyện, không phải một ô đánh dấu: viết cho <a href=\"mailto:hello@welance.com\">hello@welance.com</a> và chúng tôi sẽ nói thẳng điều gì khả thi — kể cả chạy trên các mô hình do chúng tôi chọn, hoặc bàn giao bản triển khai để bạn tự vận hành. Giấy phép MIT; tự lưu trữ là một quyền, không phải một ân huệ.",
    "data.eb4": "những giới hạn thành thật",
    "data.limits": "Chúng tôi không kiểm soát việc lưu giữ của nhà cung cấp: khi brief đã tới Anthropic hay OpenRouter thì điều khoản của họ áp dụng, và bạn nên đọc nếu nội dung nhạy cảm. Dịch vụ công khai có giới hạn tần suất theo IP và chạy trên TLS, nhưng đây là một dịch vụ mã nguồn mở nhỏ, không phải sản phẩm tuân thủ. Với thứ thật sự bí mật: mang khoá riêng, gửi no_cache, hoặc tự chạy bản của mình.",

    /* ---------- integrate.html + calculators.html ---------- */
    "int.crumb": "tích hợp",
    "int.h1": "Đặt thước đo vào quy trình của bạn",
    "int.thesis": "Bốn lối vào, từ «dán cái này» đến «gọi cái này». Tất cả đều tới cùng một thước đo: điểm số do mã tính, và một cổng có thể từ chối. Chọn lối hợp với cách bạn đang làm — hai lối đầu không cần biết kỹ thuật.",
